input.command:
pnpm list --json --depth 0 -r 2>/dev/null | node -e "
const data = JSON.parse(require('fs').readFileSync('/dev/stdin','utf8'));
data.forEach(pkg => {
  const deps = pkg.dependencies || {};
  const internal = Object.entries(deps).filter(([k]) => k.startsWith('@cipherbox/'));
  if (internal.length > 0) {
    console.log(pkg.name + ':');
    internal.forEach(([k,v]) => console.log('  -> ' + k));
  }
});
" 2>/dev/null || echo "pnpm list failed, trying alternative"

cargo metadata --no-deps --format-version 1 2>/dev/null | node -e "
const data = JSON.parse(require('fs').readFileSync('/dev/stdin','utf8'));
data.packages.forEach(pkg => {
  const internal = pkg.dependencies.filter(d => d.path);
  if (internal.length > 0) {
    console.log(pkg.name + ' (' + pkg.version + '):');
    internal.forEach(d => console.log('  -> ' + d.name));
  }
});
" 2>/dev/null || echo "cargo metadata failed"

